package cn.mop.api;
import cn.mop.domain.DomainException;
import cn.mop.domain.contact.CustomerContact;
import cn.mop.domain.contact.CustomerContact.*;
import java.time.LocalTime;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class CustomerContactTest {
    CustomerContact contact(Set<Role> roles,boolean enabled){return new CustomerContact("明确合成联系人",roles,null,null,null,null,null,enabled);}
    CustomerContact decision(){return contact(Set.of(Role.DECISION_MAKER),true);}
    @Test void explicitFieldsAndRolesPreserveOriginalNoIdentityOrChannelClaim(){var roles=EnumSet.of(Role.REPORTER,Role.DECISION_MAKER);var prefs=EnumSet.of(Priority.P1,Priority.P4);var c=new CustomerContact("合成 联系人",roles,"+8613800000000","Example+tag@example.test","explicit-user-id",prefs,new QuietWindow(true,LocalTime.of(22,0),LocalTime.of(7,0)),true);roles.clear();prefs.clear();assertEquals(2,c.roles().size());assertEquals(2,c.preferredPriorities().size());assertEquals("Example+tag@example.test",c.email());assertEquals("SELF_REPORTED_UNVERIFIED",c.contactVerification());assertEquals("NOT_VERIFIED",c.channelVerification());assertEquals("CONFIG_PENDING",c.notificationRoutingStatus());assertNull(c.deliveryEligible());assertFalse(c.identityBindingCreated());assertFalse(c.notificationDispatched());}
    @Test void missingChannelsAndUnknownPreferenceDoNotBecomeEmptyOrVerified(){var c=decision();assertNull(c.mobile());assertNull(c.email());assertNull(c.wecomUserId());assertNull(c.preferredPriorities());assertNull(c.quietWindow());assertNull(c.deliveryEligible());var none=new CustomerContact("测试",Set.of(Role.REPORTER),null,null,null,Set.of(),new QuietWindow(false,null,null),true);assertTrue(none.preferredPriorities().isEmpty());assertEquals(false,none.quietWindow().enabled());}
    @Test void disabledContactNeverBecomesEligibleDespiteDecisionRole(){var c=contact(Set.of(Role.DECISION_MAKER),false);assertFalse(c.enabledDecisionMaker());assertEquals(false,c.deliveryEligible());}
    @Test void immutableRoleAndPrioritySets(){var c=new CustomerContact("测试",Set.of(Role.REPORTER),null,null,null,Set.of(Priority.P1),null,true);assertThrows(UnsupportedOperationException.class,()->c.roles().add(Role.DECISION_MAKER));assertThrows(UnsupportedOperationException.class,()->c.preferredPriorities().add(Priority.P2));}
    @Test void nameRolesAndUnicodeAreBoundedWithoutSilentTrimming(){for(String name:Arrays.asList(null,"","　\u00a0","x\n","x\ud800","名".repeat(201)))assertThrows(DomainException.class,()->new CustomerContact(name,Set.of(Role.REPORTER),null,null,null,null,null,true));assertThrows(DomainException.class,()->contact(Set.of(),true));assertThrows(DomainException.class,()->contact(null,true));assertEquals("  测试  ",new CustomerContact("  测试  ",Set.of(Role.REPORTER),null,null,null,null,null,true).name());}
    @Test void mobileRequiresExplicitInternationalNumberAndNoDefaultCountry(){for(String mobile:List.of("13800000000","+08613800000000","+1 3800000000","+"+"1".repeat(16),""))assertThrows(DomainException.class,()->new CustomerContact("测试",Set.of(Role.REPORTER),mobile,null,null,null,null,true));}
    @Test void asciiEmailValidationDoesNotClaimDelivery(){for(String email:List.of("","a","a@@example.test","a@localhost","a..b@example.test",".a@example.test","a@-example.test","a@example..test","a@example.test ","a".repeat(65)+"@example.test"))assertThrows(DomainException.class,()->new CustomerContact("测试",Set.of(Role.REPORTER),null,email,null,null,null,true));}
    @Test void wecomIdIsBoundedSelfReportedTextNotVendorIdentityCheck(){for(String id:List.of("","　","x\t","x".repeat(257)))assertThrows(DomainException.class,()->new CustomerContact("测试",Set.of(Role.REPORTER),null,null,id,null,null,true));}
    @Test void quietWindowExplicitUnknownDisabledAndCrossMidnight(){assertNull(new QuietWindow(null,null,null).enabled());var c=new QuietWindow(true,QuietWindow.parseMinute("22:30"),QuietWindow.parseMinute("07:15"));assertTrue(c.crossesMidnight());assertEquals("Asia/Shanghai",c.zone());assertFalse(new QuietWindow(true,LocalTime.of(8,0),LocalTime.of(9,0)).crossesMidnight());}
    @Test void quietAmbiguousOrPartialWindowsRejected(){assertThrows(DomainException.class,()->new QuietWindow(true,LocalTime.NOON,LocalTime.NOON));assertThrows(DomainException.class,()->new QuietWindow(true,null,LocalTime.NOON));assertThrows(DomainException.class,()->new QuietWindow(false,LocalTime.NOON,null));assertThrows(DomainException.class,()->new QuietWindow(null,LocalTime.NOON,null));assertThrows(DomainException.class,()->new QuietWindow(true,LocalTime.of(1,1,1),LocalTime.NOON));for(String s:List.of("7:00","24:00","12:00:00","12:60"," 12:00"))assertThrows(DomainException.class,()->QuietWindow.parseMinute(s));}
    @Test void firstContactMustEstablishEnabledDecisionMaker(){assertEquals(1,CustomerContact.requireDecisionMakerAfterChange(0,null,decision()));assertEquals("LAST_ENABLED_DECISION_MAKER",assertThrows(DomainException.class,()->CustomerContact.requireDecisionMakerAfterChange(0,null,contact(Set.of(Role.REPORTER),true))).code);}
    @Test void finalDecisionCannotBeRemovedDisabledOrLoseRole(){for(CustomerContact next:Arrays.asList(null,contact(Set.of(Role.DECISION_MAKER),false),contact(Set.of(Role.REPORTER),true)))assertEquals(409,assertThrows(DomainException.class,()->CustomerContact.requireDecisionMakerAfterChange(1,decision(),next)).status);assertEquals(1,CustomerContact.requireDecisionMakerAfterChange(1,decision(),decision()));}
    @Test void otherEnabledDecisionAllowsChangesAndPromotionAddsOne(){assertEquals(1,CustomerContact.requireDecisionMakerAfterChange(2,decision(),null));assertEquals(2,CustomerContact.requireDecisionMakerAfterChange(1,contact(Set.of(Role.REPORTER),true),decision()));assertEquals(1,CustomerContact.requireDecisionMakerAfterChange(1,contact(Set.of(Role.REPORTER),true),null));}
    @Test void inconsistentCountsAndOverflowFailClosedWithoutPretendingConcurrencyProof(){assertThrows(DomainException.class,()->CustomerContact.requireDecisionMakerAfterChange(-1,null,decision()));assertThrows(DomainException.class,()->CustomerContact.requireDecisionMakerAfterChange(0,decision(),decision()));assertThrows(DomainException.class,()->CustomerContact.requireDecisionMakerAfterChange(1,null,null));assertThrows(DomainException.class,()->CustomerContact.requireDecisionMakerAfterChange(Long.MAX_VALUE,null,decision()));}
}
